//! ai.rs — DATA TWIN of skills/engine/canonical-actions/ai.mjs, generated by the crossing's expand.mjs.
//! NAMES ARE CONTRACT: statics carry the exact JS export names. The value is the JS
//! value, pressed at expansion time and proven by the conform 'const' lane (ε0 full-value
//! equality). Drift watch re-opens the unit if the JS source changes.
// QUALITY: 78/100 — generated data twin: proven byte-fidelity (ε0 full-value), embedded blob unreadable by design
use serde_json::Value;
use std::sync::LazyLock;

pub static ACTIONS: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(r#"[{"name":"system.ai.log.export","description":"FEAT-PROMPT-STUDY: dump saved AI prompt+response pairs from brain.ai_calls to readable .md files for offline prompt-quality study (OpenRouter has no API for this — the data is local). input: {out_dir (required), prompt_name?, since_ts?, real_only=true}. Defaults to real (non-cached) exchanges. Returns {exported, by_prompt, out_dir}.","owner_agent":"system","steps_json":"[{\"skill\":\"ai-log-export\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.ai.call","description":"Single chokepoint for every AI invocation. Resolves prompt + router + provider, hashes input, cache-checks (prompt_id, input_hash, tier, temperature), dispatches via injected or default provider, validates output against brain.prompt_output_fields, persists ai_calls + ai_call_outputs rows (no JSON blobs). Returns {ai_call_id, output_kv, cached, cost_usd}.","owner_agent":"system","steps_json":"[{\"skill\":\"ai-call\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.ai.call.replay","description":"Replay a stored ai_call by reconstructing input_kv from brain.ai_call_inputs, re-rendering the prompt at the version the original ran, and re-submitting to the same (or overridden) provider+tier+temperature. Bypasses the cache. The new ai_calls row is tagged replay_of_id pointing at the original. Diffs outputs and returns {original_ai_call_id, replay_ai_call_id, identical, diff_count, output_diff_md}. Useful for isolating provider drift, verifying determinism (high+freezed should match), and debugging hallucinations.","owner_agent":"system","steps_json":"[{\"skill\":\"ai-call-replay\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.ai.call.detail","description":"Render an AI interaction as a complete record — pure observability, no writes. Two modes: LIST filters by agent/tier/prompt_name/since_ts → rows of {id, ts, agent, prompt_name, tier, tokens, cost, outcome, card_slug} (desc); DETAIL takes one call id → the full payload (rendered prompt, input_kv, output_kv tree, raw response if validation failed, cost breakdown). Powers the chat trace + cost-center call inspection.","owner_agent":"system","steps_json":"[{\"skill\":\"ai-call-detail\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.ai.route","description":"Deterministic task_kind → {tier (low/mid/high), temperature (freezed/cold/warm/hot/hell), max_tokens, rationale} lookup. Reads brain.routing_defaults. Optional budget_remaining_usd triggers tier degradation when high-tier cost exceeds remaining. Unknown kinds fall back to mid+cold with a flag. Pure: same input → same output.","owner_agent":"system","steps_json":"[{\"skill\":\"ai-route\",\"input\":\"$.input\",\"as\":\"route\"}]","returns":"$.results.route","on_failure":"abort"},{"name":"system.ai.provider.set-active","description":"GOD: set a single brain.ai_providers row as active within its tier. Deactivates all other providers in that tier first (one-active-per-tier invariant). Input: {provider_id}. Reachable only via god-mode.","owner_agent":"god","steps_json":"[{\"skill\":\"god-ai-provider-set-active\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.ai.provider.test","description":"Fire a hello-world test call at a specific provider row (by id) to verify reachability. Returns { ok, latency_ms, tokens_in, tokens_out, response_preview, error? }. Does NOT write brain.ai_calls.","owner_agent":"system","steps_json":"[{\"skill\":\"provider-test-call\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"}]"#).expect("ACTIONS: embedded JSON is valid by construction")
});

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::Value;

    #[test]
    fn actions_parses_with_the_pressed_shape() {
        let v: &Value = &ACTIONS;
        let a = v.as_array().expect("array");
        assert_eq!(a.len(), 7, "pressed length");
        let mut names: Vec<&str> = a.iter().map(|x| x["name"].as_str().expect("name")).collect();
        let n = names.len();
        names.sort(); names.dedup();
        assert_eq!(names.len(), n, "names unique");
    }

}
